export type LaunchPlansIndexData = {
    body?: never;
    path: {
        /**
         * The workspace ID
         */
        workspace: number;
    };
    query?: {
        page?: number;
        /**
         * Continue using next_cursor with the same filters; rule lists use an immutable rule ID, other lists an offset or object ID.
         */
        cursor?: number;
        /**
         * Maximum complete rows; the byte budget may return fewer. Defaults to 25.
         */
        per_page?: number;
    };
    url: '/workspaces/{workspace}/admin/plans';
};

export type LaunchPlansIndexErrors = {
    /**
     * An active principal is required.
     */
    401: ErrorMessage;
    /**
     * The principal lacks read access to this account.
     */
    403: ErrorMessage;
    /**
     * Workspace or plan not found.
     */
    404: ApiRouteNotFound;
};

export type LaunchPlansIndexError = LaunchPlansIndexErrors[keyof LaunchPlansIndexErrors];

export type LaunchPlansIndexResponses = {
    /**
     * Plans with their current review version. Result projections share the 80,000-byte MCP JSON budget; defaults are bounded, next_cursor continues complete rows, and oversized single rows are explicitly refused. Plan creative continuation uses the read endpoint; proposal continuation uses the batch read endpoint.
     */
    200: {
        plans: {
            data: Array<DeploymentPlanRead>;
            current_page: number;
            per_page: number;
            total: number;
            last_page: number;
            /**
             * Always present. The next row offset, or null when the list is complete.
             */
            next_cursor: number | null;
            truncated: boolean;
            /**
             * Always present. Page and per_page for aligned offsets, cursor and per_page after a byte-limited page, or null when complete.
             */
            next_page_arguments: {
                page: number;
                per_page: number;
            } | {
                cursor: number;
                per_page: number;
            } | null;
            continuation: string;
        };
    };
};

export type LaunchPlansIndexResponse = LaunchPlansIndexResponses[keyof LaunchPlansIndexResponses];

